"""Database version string parsing utilities."""
def is_valid_version(version: str) -> bool:
    parts = version.split(".")
    return len(parts) >= 2 and all(p.isdigit() for p in parts)

def extract_major_version(version: str) -> int:
    return int(version.split(".")[0])
